independent.solution:
pages = {
    1: {"data": [1, 2, 3], "page": 1, "total_pages": 3},
    2: {"data": [4, 5, 6], "page": 2, "total_pages": 3},
    3: {"data": [7, 8], "page": 3, "total_pages": 3},
}
script = iter([(200, {}, pages[1]), (429, {"Retry-After": "3"}, None), (200, {}, pages[2]),
               (503, {}, None), (503, {}, None), (200, {}, pages[3])])

def send(page):
    return next(script)

waits = []

def fetch_all(send, sleep):
    items, page = [], 1
    while True:
        attempt = 0
        while True:
            status, headers, body = send(page)
            if status < 400:
                break
            if status == 429:
                sleep(float(headers['Retry-After']))
            elif status >= 500:
                sleep(1.0 * 2 ** attempt)
                attempt += 1
            else:
                raise RuntimeError(f'HTTP {status}')
        items += body['data']
        if page >= body['total_pages']:
            return items
        page += 1

print(fetch_all(send, waits.append))
print(waits)
